import{c as l,Z as o,Q as r,j as n,m as s,o as t}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"沉醉东风·渔夫","description":"","frontmatter":{"title":"沉醉东风·渔夫","author":"白朴","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/5.md","filePath":"books/shici/yuanqu/5.md"}'),u={name:"books/shici/yuanqu/5.md"};function h(c,a,p,d,q,_){const e=o("PoemAuthor"),i=o("PoemNav");return r(),n("div",null,[a[0]||(a[0]=s('<h1 id="沉醉东风·渔夫" tabindex="-1">沉醉东风·渔夫 <a class="header-anchor" href="#沉醉东风·渔夫" aria-label="Permalink to &quot;沉醉东风·渔夫&quot;">​</a></h1><p><strong>[元] <a href="/authors/baipu.html">白朴</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>黄芦岸白蘋渡口，绿柳堤红蓼滩头。 虽无刎颈交，却有忘机友， 点秋江白鹭沙鸥。 傲杀人间万户侯，不识字烟波钓叟。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>沉醉东风：曲牌名</li><li>黄芦：枯黄的芦苇</li><li>白蘋：一种水生植物，俗称浮萍</li><li>红蓼：一种水边植物，开红花</li><li>刎颈交：可以同生死、共患难的朋友</li><li>忘机友：没有机心、淡泊名利的朋友，此处指白鹭沙鸥</li><li>点：点缀</li><li>傲杀：傲视至极</li><li>万户侯：古代爵位，食邑万户，泛指高官厚禄</li><li>烟波钓叟：在烟波浩渺中垂钓的老翁</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>枯黄的芦苇岸边，白蘋丛生的渡口；绿柳低垂的堤岸，红蓼盛开的滩头。 虽然没有可以同生共死的刎颈之交，却有那些没有机心的忘机之友——点缀在秋江上的白鹭和沙鸥。 （这种生活）傲视人间那些万户侯，（我就是那个）不识字的烟波钓叟。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首散曲描绘了一幅秋江垂钓图，表现了渔夫淡泊名利、超然物外的生活情趣，是元曲中隐逸题材的代表作。</p><p>&quot;黄芦岸白蘋渡口，绿柳堤红蓼滩头&quot;，开篇以两组对偶句描绘秋江景色。黄、白、绿、红四种色彩交相辉映，构成了一幅明丽而富有诗意的秋江图，点明了渔夫的居住环境。</p><p>&quot;虽无刎颈交，却有忘机友，点秋江白鹭沙鸥&quot;，写渔夫的精神世界。他没有世俗的知己，却有白鹭沙鸥这些&quot;忘机友&quot;相伴。&quot;忘机&quot;二字是关键，指没有机心、不图名利，这正是渔夫精神境界的写照。</p><p>&quot;傲杀人间万户侯，不识字烟波钓叟&quot;，以傲视王侯作结，将渔夫的形象升华。一个&quot;傲&quot;字，写出了隐士不慕荣利、蔑视权贵的高洁品格。&quot;不识字&quot;并非真的目不识丁，而是表明不涉世事、不通世故的质朴与纯真。全曲语言清丽，意境悠远，表达了作者对归隐生活的向往。</p>',13)),t(e,{name:"白朴",years:"1226年－约1306年",desc:"字太素，号兰谷，元代著名戏曲作家、散曲家，元曲四大家之一。其散曲风格清丽婉约，多写隐逸生活。",link:"/authors/baipu"}),t(i)])}const f=l(u,[["render",h]]);export{b as __pageData,f as default};
